```python
# python: docs helper (sync streaming with resume)
import time
class ResumeableError(Exception):
    def __init__(self, msg, token=None):
        super().__init__(msg)
        self.resume_token = token

def stream_with_resume(client, req, max_retries=3):
    retries = 0
    token = None
    while True:
        try:
            for ev in client.stream(req, resume_token=token):
                if ev.type == 'resume_token':
                    token = ev.token
                yield {"type": ev.type, "data": ev.data, "resume_token": token}
            break
        except TransientError as e:
            if retries >= max_retries:
                raise ResumeableError('max retries', token)
            retries += 1
            time.sleep(2 ** retries * 0.1)
            continue
```

sam: looks straightforward. for ts/js we should include both a Promise/callback example and an async-iterator one. PR currently has the async-iterator; i'll add a short callback snippet.

```ts
// typescript: async generator shim
async function* streamWithResume(client, req, maxRetries = 3) {
  let token: string | null = null
  let retries = 0
  while (true) {
    try {
      for await (const ev of client.stream(req, { resumeToken: token })) {
        if (ev.type === 'resume_token') token = ev.token
        yield { type: ev.type, payload: ev.data, resumeToken: token }
      }
      break
    } catch (err) {
      if (retries >= maxRetries) {
        const e = new Error('max retries') as any
        e.resumeToken = token
        throw e
      }
      retries++
      await new Promise(r => setTimeout(r, Math.pow(2, retries) * 100))
      continue
    }
  }
}
```

