li: i'll push the Go snippet now. here's what i'll add in Go to be explicit about context and error type:

```go
// go: context-aware shim
package examples

import (
  "context"
  "errors"
  "time"
)

type ResumeableError struct {
  Err error
  Token string
}

func (e *ResumeableError) Error() string { return e.Err.Error() }
func (e *ResumeableError) Unwrap() error { return e.Err }

func StreamWithResume(ctx context.Context, client Client, req Request, maxRetries int) (<-chan Event, <-chan error) {
  out := make(chan Event)
  errc := make(chan error, 1)
  go func() {
    defer close(out)
    var token string
    retries := 0
    for {
      select {
      case <-ctx.Done():
        errc <- ctx.Err()
        return
      default:
      }
      evc, err := client.Stream(ctx, req, token)
      if err != nil {
        if retries >= maxRetries {
          errc <- &ResumeableError{Err: errors.New("max retries"), Token: token}
          return
        }
        retries++
        select {
        case <-ctx.Done():
          errc <- ctx.Err()
          return
        case <-time.After(time.Duration(1<<retries) * 100 * time.Millisecond):
        }
        continue
      }
      for ev := range evc {
        if ev.Type == "resume_token" {
          token = ev.Token
        }
        select {
        case out <- ev:
        case <-ctx.Done():
          errc <- ctx.Err()
          return
        }
      }
      break
    }
    errc <- nil
  }()
  return out, errc
}
```

